  const startCustomTimer = (id: string) => { setRunningTimers(prev => { const state = prev[id]; if (!state || state.isRunning || state.timeLeft <= 0) return prev; const newState = { ...prev }; const newTimerState = { ...state }; if (newTimerState.audio) { newTimerState.audio.pause(); newTimerState.audio = undefined; } newTimerState.isRunning = true; newTimerState.finished = false; const intervalId = setInterval(() => { setRunningTimers(curr => { if (!curr[id]) { clearInterval(intervalId); return curr; } const upd = { ...curr }; const t = { ...upd[id] }; if (!t.isRunning && t.intervalRef) { clearInterval(t.intervalRef); t.intervalRef=null; upd[id]=t; return upd; } if (t.timeLeft <= 1) { clearInterval(t.intervalRef!); t.isRunning = false; t.finished = true; t.timeLeft = 0; t.intervalRef = null; if (!t.audio) { try { const audio = new Audio('...'); audio.loop=true; audio.play().catch(console.error); t.audio=audio; } catch {} } } else { t.timeLeft -= 1; } upd[id]=t; return upd; }); }, 1000); newTimerState.intervalRef = intervalId; newState[id] = newTimerState; return newState; }); };
  const pauseCustomTimer = (id: string) => { setRunningTimers(prev => { const state = prev[id]; if (!state || !state.isRunning) return prev; const newState = { ...prev }; const newTimerState = { ...state }; if (newTimerState.intervalRef) { clearInterval(newTimerState.intervalRef); newTimerState.intervalRef = null; } newTimerState.isRunning = false; newState[id] = newTimerState; return newState; }); };
  const resetCustomTimer = (id: string) => { const srcData = customTimers.find(t => t.id === id)?.data; if (!srcData) { setRunningTimers(prev => { const {[id]:_, ...rest}=prev; return rest; }); return; } const defaultTime = srcData.time; setRunningTimers(prev => { const state = prev[id]; const newState = { ...prev }; const newTimerState = state ? { ...state } : { isRunning: false, timeLeft: defaultTime, intervalRef: null, finished: !defaultTime, audio: undefined }; if (newTimerState.intervalRef) clearInterval(newTimerState.intervalRef); newTimerState.isRunning = false; newTimerState.timeLeft = defaultTime; newTimerState.intervalRef = null; newTimerState.finished = !defaultTime; if (newTimerState.audio) { newTimerState.audio.pause(); newTimerState.audio = undefined; } newState[id] = newTimerState; return newState; }); };
  const handleEditTimerClick = (id: string, name: string, time: number) => { if (runningTimers[id]?.isRunning) pauseCustomTimer(id); setEditingTimerId(id); setEditingTimerName(name); setEditingTimerMinutes(String(Math.max(1, Math.floor(time / 60)))); };
